--###############
--## MONITORS ###
--###############

-- See https://wiki.hypr.land/Configuring/Monitors/
-- monitor=,preferred,auto,auto
-- monitor = eDP-1,2880x1800@90,0x0,1.5
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.monitor({
	output = "eDP-1",
	mode = "2880x1800@60",
	position = "0x0",
	scale = "1.5",
})

-- monitor = HDMI-A-1,1920x1080@144,480x-1080,1 #kosan
-- monitor = HDMI-A-1,1920x1080@144,0x-1080,1 #kosan
hl.monitor({
	output = "HDMI-A-1",
	mode = "1920x1080@75",
	position = "1920x0",
	scale = "1",
})

--##################
--## MY PROGRAMS ###
--##################

-- See https://wiki.hypr.land/Configuring/Keywords/

-- Set programs that you use
local terminal = "kitty"
local fileManager = "dolphin"
local menu = "hyprlauncher"

--################
--## AUTOSTART ###
--################

-- --- SYSTEM & ENVIRONMENT DAEMONS ---
-- Import Hyprland environment into DBus/systemd for screen sharing & portals

-- Force GTK/Qt applications to default to Dark Theme

-- --- UI & NOTIFICATIONS ---

-- --- WALLPAPER DAEMON ---
-- Chain daemon startup with restore to prevent race conditions (use swww or awww)

-- --- CLIPBOARD MANAGER ---
-- Monitor text and image buffers with capped item limits

-- rclone gdrive
-- exec-once = rclone mount gdrive-work: ~/Gdrive/work --vfs-cache-mode full --vfs-cache-max-age 24h --vfs-write-back 5s --daemon

--############################
--## ENVIRONMENT VARIABLES ###
--############################

-- See https://wiki.hypr.land/Configuring/Environment-variables/
hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

-- Dual GPU setup
hl.env("AQ_DRM_DEVICES", "/dev/dri/card2:/dev/dri/card1")

-- Desktop integration
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")
hl.env("GDK_BACKEND", "wayland,x11")

-- --- UNIFIED QT WAYLAND SCALING ---
-- Force Qt5 and Qt6 to use native Wayland protocols
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")

-- Let Hyprland compositor handle scaling naturally for Qt apps
hl.env("QT_AUTO_SCREEN_SCALE_FACTOR", "0")
hl.env("QT_SCALE_FACTOR_ROUNDING_POLICY", "PassThrough")

-- Prevent Qt from forcing desktop-DPI multiplier on top of Wayland
hl.env("QT_ENABLE_HIGHDPI_SCALING", "0")
hl.env("QT_SCALE_FACTOR", "1")

-- Browser Wayland support
hl.env("MOZ_ENABLE_WAYLAND", "1")

-- trying new scaling settings
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "auto")

hl.config({
	xwayland = {
		force_zero_scaling = true,
	},
})

hl.config({
	cursor = {
		no_hardware_cursors = 2,
		enable_hyprcursor = true,
	},
})

