-- Refer to https://wiki.hypr.land/Configuring/Variables/

-- https://wiki.hypr.land/Configuring/Variables/#general

hl.config({
	general = {
		-- perfect
		-- gaps_in = 2
		-- gaps_out = 2, 3, 3, 3
		gaps_in = 3,
		gaps_out = { top = 3, right = 4, bottom = 4, left = 4 },
		border_size = 2,
		-- https://wiki.hypr.land/Configuring/Variables/#variable-types for info about colors
		-- default colors
		-- col.active_border = rgba(33ccffee) rgba(00ff99ee) 45deg
		-- col.inactive_border = rgba(595959aa)
		--sazabi color
		col = {
			active_border = { colors = { "rgba(f38ba8ee)", "rgba(fab387ee)" }, angle = 45 },
			inactive_border = "rgba(181825aa)",
		},
		-- Set to true enable resizing windows by clicking and dragging on borders and gaps
		resize_on_border = false,
		-- Please see https://wiki.hypr.land/Configuring/Tearing/ before you turn this on
		allow_tearing = false,
		layout = "dwindle",
	},
})

-- https://wiki.hypr.land/Configuring/Variables/#decoration

hl.config({
	decoration = {
		-- rounding = 5
		rounding = 6,
		rounding_power = 2,
		-- Change transparency of focused and unfocused windows
		active_opacity = 1.0,
		inactive_opacity = 0.95,
		-- shadow {
		--     enabled = true
		--     range = 4
		--     render_power = 3
		--     color = rgba(1a1a1aee)
		-- }
		shadow = {
			enabled = false, -- Try this if it still feels 'heavy'
		},
		-- https://wiki.hypr.land/Configuring/Variables/#blur
		-- blur {
		--     enabled = true
		--     size = 3
		--     passes = 1
		--
		--     vibrancy = 0.1696
		-- }
		--
		blur = {
			enabled = false,
		},
	},
})

-- New syntax for Waybar blur
hl.layer_rule({
	match = { namespace = "waybar" },
	blur = false,
})

hl.layer_rule({
	match = { namespace = "waybar" },
	ignore_alpha = 0.1,
})

-- Hyprland now uses 'animation' as a layerrule instead of 'transition'
hl.layer_rule({
	match = { namespace = "waybar" },
	animation = "fade",
})

-- https://wiki.hypr.land/Configuring/Variables/#animations
hl.config({
	animations = {
		enabled = true,
		-- This curve starts fast but settles much more "linearly" at the end
		-- It avoids the long "trailing" slow-motion effect
	},
})

hl.curve("snap", { type = "bezier", points = { { 0.1, 1 }, { 0.3, 1 } } })
hl.animation({
	leaf = "windows",
	enabled = true,
	speed = 2,
	bezier = "snap",
	style = "slide",
})
hl.animation({
	leaf = "workspaces",
	enabled = true,
	speed = 3,
	bezier = "snap",
	style = "slide",
})
hl.animation({
	leaf = "windowsOut",
	enabled = true,
	speed = 2,
	bezier = "snap",
	style = "popin 80%",
})
hl.animation({
	leaf = "fade",
	enabled = true,
	speed = 2,
	bezier = "snap",
})

-- Ref https://wiki.hypr.land/Configuring/Workspace-Rules/
-- "Smart gaps" / "No gaps when only"
-- uncomment all if you wish to use that.
-- workspace = w[tv1], gapsout:0, gapsin:0
-- workspace = f[1], gapsout:0, gapsin:0
-- windowrule {
--     name = no-gaps-wtv1
--     match:float = false
--     match:workspace = w[tv1]
--
--     border_size = 0
--     rounding = 0
-- }
-- ==========================================
-- ✨ SMART GAPS (Dynamic Windows Rules)
-- ==========================================

-- When there is only 1 visible tiled window (w[tv1]), bump gaps up to 10
-- workspace = w[tv1], gapsout:8 30 16 30, gapsin:10, rounding:10
hl.window_rule({
	name = "single-window-rounding",
	match = {
		float = false,
		workspace = "w[tv1]",
	},
	rounding = 5,
})

hl.window_rule({
	name = "multi-window-rounding",
	match = {
		float = false,
		workspace = "w[tv2-99]",
	},
	rounding = 5,
})

-- When an app is truly fullscreen (f[1]), remove all gaps completely
-- workspace = f[1], gapsout:0, gapsin:0
--
