-- See https://wiki.hypr.land/Configuring/Keywords/
local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- --- ESSENTIAL APPS & LAUNCHERS ---
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + W", hl.dsp.window.close())
hl.bind(mainMod .. " + SHIFT + B", hl.dsp.exec_cmd('xdg-open "https://"'))
hl.bind(mainMod .. " + O", hl.dsp.exec_cmd("obsidian"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd("~/.config/rofi/launchers/type-6/launcher.sh"))
hl.bind(
	mainMod .. " + PERIOD",
	hl.dsp.exec_cmd(
		'rofimoji --action copy --selector-args "-theme ~/.config/rofi/emoji.rasi" && sleep 0.1 && wtype -M ctrl v'
	)
)
hl.bind(
	mainMod .. " + V",
	hl.dsp.exec_cmd(
		"cliphist list | rofi -dmenu -theme ~/.config/rofi/launchers/type-6/style-1.rasi | cliphist decode | wl-copy && wtype -M ctrl v"
	)
)
hl.bind("SHIFT + Print", hl.dsp.exec_cmd("hyprshot -m region --clipboard-only"))

hl.bind(mainMod .. " + N", hl.dsp.exec_cmd("swaync-client -t -sw"))

-- --- SESSION & POWER CONTROLS ---
-- Manual Lock (Prevents fat-fingering $mainMod + Left arrow)
hl.bind(mainMod .. " + SHIFT + L", hl.dsp.exec_cmd("loginctl lock-session"))

-- Power Menu (wlogout)
hl.bind(mainMod .. " + ESCAPE", hl.dsp.exec_cmd("pkill wlogout || wlogout"))
hl.bind(
	mainMod .. " + M",
	hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch exit")
)

-- --- WINDOW MANAGEMENT & LAYOUTS ---
-- Cleaned Floating/Fullscreen toggles (No more overlapping $mainMod + F actions)
-- bind = $mainMod, F, togglefloating,
-- # Toggle floating AND immediately resize to 1600x1000 + center on screen

-- hl.bind(mainMod .. " + F", function()
-- 	hl.dispatch(hl.dsp.window.float({ action = "toggle" }))
-- 	hl.dispatch(hl.dsp.window.resize({ x = 1600, y = 1000, relative = false }))
-- end)
hl.bind(mainMod .. " + F", function()
	hl.dispatch(hl.dsp.window.float({ action = "toggle" }))
	hl.dispatch(hl.dsp.window.resize({ x = 1600, y = 1000, relative = false }))
	hl.timer(function()
		hl.dispatch(hl.dsp.exec_raw("exec hyprctl dispatch centerwindow"))
	end, { timeout = 50, type = "oneshot" })
end)

hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" }))
hl.bind(mainMod .. " + C", hl.dsp.window.center())

hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))
hl.bind("SUPER + SHIFT + X", hl.dsp.layout("swapsplit"))

-- Move focus (Arrow keys)
hl.bind(mainMod .. " + left", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down", hl.dsp.focus({ direction = "down" }))

-- Swap windows (Shift + Arrow keys)
hl.bind("SUPER + SHIFT + left", hl.dsp.window.swap({ direction = "l" }))
hl.bind("SUPER + SHIFT + right", hl.dsp.window.swap({ direction = "r" }))
hl.bind("SUPER + SHIFT + up", hl.dsp.window.swap({ direction = "u" }))
hl.bind("SUPER + SHIFT + down", hl.dsp.window.swap({ direction = "d" }))

-- Window Resizing
hl.bind(mainMod .. " + EQUAL", hl.dsp.window.resize({ x = 40, y = 40, relative = true }), { repeating = true })
hl.bind(mainMod .. " + MINUS", hl.dsp.window.resize({ x = -40, y = -40, relative = true }), { repeating = true })
hl.bind(mainMod .. " + SHIFT + EQUAL", hl.dsp.window.resize({ x = 0, y = -40, relative = true }), { repeating = true })
hl.bind(mainMod .. " + SHIFT + MINUS", hl.dsp.window.resize({ x = 0, y = 40, relative = true }), { repeating = true })

