-- See https://wiki.hypr.land/Configuring/Window-Rules/ for more
-- See https://wiki.hypr.land/Configuring/Workspace-Rules/ for workspace rules

-- Example windowrules that are useful

hl.window_rule({
	name = "suppress-maximize-events",
	match = {
		class = ".*",
	},
	-- Ignore maximize requests from all apps. You'll probably like this.
	suppress_event = "maximize",
})

hl.window_rule({
	name = "fix-xwayland-drags",
	match = {
		class = "^$",
		title = "^$",
		xwayland = true,
		float = true,
		fullscreen = false,
		pin = false,
	},
	-- Fix some dragging issues with XWayland
	no_focus = true,
})

-- Hyprland-run windowrule
hl.window_rule({
	name = "move-hyprland-run",
	match = {
		class = "hyprland-run",
	},
	move = "20 monitor_h-120",
	float = true,
})

hl.window_rule({
	name = "firefox-pip",
	match = {
		class = "^(firefox)$",
		title = "^Picture-in-Picture$",
	},
	-- Match props
	-- Effects
	float = true,
	pin = true,
	animation = "none",
	size = "530 300",
	-- move = 1385 895
	move = "1380 830",
})

hl.window_rule({
	name = "brave-youtube-pip",
	match = {
		title = "^Picture in picture$",
	},
	-- Brave leaves the class empty for PiP, so we match by title only
	-- Effects
	float = true,
	pin = true,
	animation = "none",
	-- Your preferred dimensions
	size = "530 300",
	move = "1380 830",
})

hl.window_rule({
	name = "bitwarden-float",
	match = {
		class = "^brave-nngceckbapebfimnlniiiahkandclblb-Default$",
	},
	-- Match exact casing from your hyprctl output
	-- Effects
	float = true,
	center = true,
	pin = true,
	dim_around = true,
	stay_focused = true,
	-- Matching the exact case for Bitwarden
	-- opacity = 0.8 0.8
	-- Set size (important for popups)
	size = "480 700",
})

hl.window_rule({
	name = "spotify-browser-pip",
	match = {
		class = "^brave-browser-nightly$",
		title = ".* • .*",
	},
	-- Effects
	float = true,
	pin = true,
	animation = "none",
	-- Dimensions & positioning
	size = "340 340",
	move = "1570 850",
})

hl.window_rule({
	name = "browser-login-popups",
	match = {
		class = "^(brave-browser|Brave-browser)$",
		title = "^(Sign in|Log in|Authorize|Authentication|Connect|OAuth).*$",
	},
	-- Match popups originating from Brave (or any browser)
	-- Alternatively, target popups using initialTitle or role if set
	-- match:popin = true
	-- Layout & Float
	float = true,
	center = true,
	stay_focused = true,
	dim_around = true,
	-- Compact dimensions for popup windows
	size = "500 700",
})

hl.window_rule({
	match = {
		class = "firefox",
	},
	no_blur = true,
})

-- windowrule = opacity 0.6 0.6, match:float true
hl.window_rule({
	match = {
		class = "kitty",
	},
	opacity = "0.8 0.8",
})

-- bluetui & impala
hl.window_rule({
	match = {
		class = "^(impala-float|bluetui-float)$",
	},
	float = true,
})

