-- Catch common dialog titles
hl.window_rule({
	match = {
		title = "^(Confirm to replace files|File Operation Progress|Authentication Required)$",
	},
	float = true,
})

--zoom
-- Zoom Workplace rules
hl.window_rule({
	name = "zoom-main-tile",
	match = {
		class = "^(zoom)$",
		title = "^(Zoom Meeting|Zoom Workplace)$",
	},
	float = false,
})

hl.window_rule({
	name = "zoom-popups-float",
	match = {
		class = "^(zoom)$",
		title = "^(Settings|Participants|Chat|Meeting Information|Breakout Rooms|Select a window)$",
	},
	float = true,
	center = true,
})

hl.window_rule({
	name = "termius-float",
	match = { class = "^(Termius|termius-app)$" },
	float = true,
	size = { 1200, 800 },
	center = true,
})

hl.config({
	group = {
		col = {
			border_active = "rgba(89b4faee)", -- Active group border (Catppuccin Blue)
			border_inactive = "rgba(313244aa)", -- Inactive group border
		},
		groupbar = {
			enabled = true, -- Set false if you don't want the top tab bar visible
			font_size = 10,
			gradients = false,
			col = {
				active = "rgba(89b4faee)",
				inactive = "rgba(313244aa)",
			},
			text_color = "rgba(cdd6f4ff)",
		},
	},
})

hl.on("hyprland.start", function()
	hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
	hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
	hl.exec_cmd("gsettings set org.gnome.desktop.interface color-scheme 'prefer-dark'")
	hl.exec_cmd("waybar")
	hl.exec_cmd("hypridle")
	hl.exec_cmd("swayosd-server")
	hl.exec_cmd("swaync")
	hl.exec_cmd("swww-daemon || awww-daemon")
	hl.exec_cmd("sleep 0.5 && (swww restore || awww restore)")
	hl.exec_cmd("wl-paste --type text --watch cliphist -max-items 500 store")
	hl.exec_cmd("wl-paste --type image --watch cliphist -max-items 100 store")
end)
